style.css:
@-moz-document domain("yandex.com"), domain("ads.yandex"), domain("meteum.ai") {
html {
  color-scheme: dark !important;
  background-color: #030806 !important;
  scrollbar-color: #167b40 #04110a !important;
}
html {
  color: #a5ffb7 !important;
  font-family: "Cascadia Code", "Consolas", "Lucida Console", monospace !important;
  background-color: #030806 !important;
  background-image: linear-gradient(180deg,
     rgba(3, 8, 6, 0.17) 0%,
     rgba(3, 8, 6, 0.32) 55%,
     rgba(3, 8, 6, 0.55) 100%),
	   url("data:image/jpeg;base64,") !important;
  background-position: center top, center center !important;
  background-repeat: no-repeat, no-repeat !important;
  background-size: cover, cover !important;
  background-attachment: fixed, fixed !important;
  min-height: 100vh !important;
}
body {
  background-color: transparent !important;
  background-image: none !important;
  min-height: 100vh !important;
}
.page,
.Page,
.layout,
.Layout,
.main,
.Main,
.content,
.Content,
.content__main,
