.OrganicTitle,
.organic__url-text,
[class*="Title-LinkText"] {
  color: #c0ffd0 !important;
  letter-spacing: 0.015em !important;
  font-family: "Cascadia Code", "Consolas", "Lucida Console", monospace !important;
}
::selection {
  background: #00ff66 !important;
  color: #031007 !important;
}
a,
a:link,
a:visited,
[role="link"] {
  color: #63d995 !important;
  text-decoration-color: rgba(0, 255, 102, 0.34) !important;
  font-family: "Cascadia Code", "Consolas", "Lucida Console", monospace !important;
  transition: color 0.16s ease, text-shadow 0.16s ease !important;
}
a:hover,
a:focus,
[role="link"]:hover {
  color: #00ff66 !important;
  text-decoration-color: #00ff66 !important;
  text-shadow: 0 0 9px rgba(0, 255, 102, 0.47) !important;
}
.OrganicTitle-Link,
.OrganicTitle-LinkText,
.organic__url,
