}
.search2,
.search3,
.search-form,
.search2__form,
.search3__form,
.SearchForm,
[class*="SearchForm"],
[class*="SearchBox"] {
  border-radius: 12px !important;
  box-shadow: 0 0 0 1px rgba(0, 255, 102, 0.13),
              0 0 9px rgba(0, 255, 102, 0.35),
              0 0 27px rgba(0, 255, 102, 0.14) !important;
  backdrop-filter: blur(12px) !important;
}
.search2__input,
.search3__input,
.SearchInput,
.Textinput,
.input__box,
.search-form__input,
[class*="SearchInput-Wrapper"],
[class*="SearchField"] {
  background: rgba(3, 17, 10, 0.86) !important;
