  border-color: rgba(0, 255, 102, 0.38) !important;
  border-radius: 9px !important;
}
input[type="search"],
input[type="text"],
input[name="text"],
input[role="combobox"],
.input__control,
.Textinput-Control,
.search2__input input,
.search3__input input,
textarea {
  color: #cbffda !important;
  caret-color: #00ff66 !important;
  font-family: "Cascadia Code", "Consolas", "Lucida Console", monospace !important;
  background-color: rgba(2, 13, 7, 0.75) !important;
  border-color: rgba(0, 255, 102, 0.38) !important;
  outline-color: #00ff66 !important;
}
input::placeholder,
