  outline: 2px solid #00ff66 !important;
  outline-offset: 3px !important;
  box-shadow: 0 0 13px rgba(0, 255, 102, 0.5) !important;
}
button,
input[type="button"],
input[type="submit"],
.button,
.Button,
.Button2,
[class*="SearchButton"],
[class*="Button2-View"] {
  background: linear-gradient(145deg, #0b311b 0%, #06180e 100%) !important;
  color: #00ff66 !important;
