    -webkit-filter: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    mix-blend-mode: normal !important;
  }

  /* Keep real terrain, roads, map labels, pins and live tile imagery unfiltered.
     Do not remove native opacity/filters from interactive HUD or transition
     overlays, which can be needed for the map application's functionality. */
  .ymaps3x0--map canvas,
  .ymaps-2-1-79-map canvas,
  .ymaps3x0--map img,
  .ymaps-2-1-79-map img,
  [class*="map-tile"] img,
  [class*="ground-pane"] img,
  [class*="tile-container"] img {
    filter: none !important;
    -webkit-filter: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    mix-blend-mode: normal !important;
  }
}
